function maxAverageOfPath(cost) {
  const N = cost.length;
  const dp = Array.from({ length: N }, () => Array(N).fill(0));

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      if (i === 0 && j === 0) {
        dp[i][j] = cost[i][j];
      } else if (i === 0) {
        dp[i][j] = dp[i][j - 1] + cost[i][j];
      } else if (j === 0) {
        dp[i][j] = dp[i - 1][j] + cost[i][j];
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
      }
    }
  }

  const totalCost = dp[N - 1][N - 1];
  const numberOfCells = N + N - 2;
  const maxAverage = totalCost / numberOfCells;

  return maxAverage;
}

