        if (path.length === k) {
            pq.push([...path]);
            return;
        }
        visited[x][y] = true;
        for (const [dx, dy] of directions) {
            const nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                dfs(nx, ny, path.concat(grid[nx][ny]));
            }
        }
        visited[x][y] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]]);
        }
    }

    pq.sort((a, b) => a.localeCompare(b));
    return pq[0];
}

