function correct_bracketing(brackets) {
  let balance = 0;
  for (let i = 0; i < brackets.length; i++) {
    if (brackets[i] === '(') {
      balance++;
    } else if (brackets[i] === ')') {
      balance--;
      if (balance < 0) {
        return false;
      }
    }
  }
  return balance === 0;
}

