function encrypt(s) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  let encrypted = '';

  for (let char of s) {
    if (alphabet.includes(char)) {
      let index = (alphabet.indexOf(char) + (2 * 2) % 26) % 26;
      encrypted += alphabet[index];
    } else {
      encrypted += char;
    }
  }

  return encrypted;
}

function is_samepatterns(colors, patterns) {
  if (colors.length !== patterns.length) {
    return false;
  }

  const colorMap = new Map();
  const patternMap = new Map();

  for (let i = 0; i < colors.length; i++) {
    const color = colors[i];
    const pattern = patterns[i];

    if (!colorMap.has(color)) {
      colorMap.set(color, i);
    }

    if (!patternMap.has(pattern)) {
      patternMap.set(pattern, i);
    }

    if (colorMap.get(color) !== patternMap.get(pattern)) {
      return false;
    }
  }

  return true;
}

function separate_paren_groups(paren_string) {
    const result = [];
    let currentGroup = '';
    let balance = 0;

    for (const char of paren_string.replace(/\s/g, '')) {
        currentGroup += char;
        if (char === '(') balance++;
        else if (char === ')') balance--;

        if (balance === 0) {
            result.push(currentGroup);
            currentGroup = '';
        }
    }

    return result;
}

function geometric_sum(n) {
