function min_product_tuple(list1){
    let minProduct = Infinity;
    for(let i = 0; i < list1.length; i++){
        for(let j = 0; j < list1[i].length - 1; j++){
            let product = list1[i][j] * list1[i][j + 1];
            if(product < minProduct){
