function validate(n) {
    const digitCount = {};
    const digits = n.toString().split('');

    for (const digit of digits) {
        if (digitCount[digit]) {
            digitCount[digit]++;
        } else {
            digitCount[digit] = 1;
        }
    }

    for (const digit in digitCount) {
        if (digitCount[digit] > parseInt(digit)) {
            return false;
        }
    }

    return true;
}

